import{_ as a,o as t,c as s,ak as i}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Database","description":"SQLite by default or PostgreSQL for a shared instance, how to switch between them, and where retention and backups are covered.","frontmatter":{"title":"Database","description":"SQLite by default or PostgreSQL for a shared instance, how to switch between them, and where retention and backups are covered.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/database.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/database.html"}],["meta",{"property":"og:title","content":"Database | Piwi Dashboard"}],["meta",{"property":"og:description","content":"SQLite by default or PostgreSQL for a shared instance, how to switch between them, and where retention and backups are covered."}]]},"headers":[],"relativePath":"operate/database.md","filePath":"operate/database.md","lastUpdated":1790454935000}'),n={name:"operate/database.md"};function o(r,e,d,l,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h1><p>Piwi stores runs, test cases, executions, clusters and settings in a relational database. Two backends are supported: <strong>SQLite</strong> (the default, zero configuration) and <strong>PostgreSQL</strong> (for multi-user or high-concurrency deployments). Both are exercised by the project&#39;s CI on every commit, and migrations run automatically on startup either way.</p><p>Test artifacts — HTML reports, traces, attachments — do <strong>not</strong> live here; they go to <a href="./storage.html">file storage</a>.</p><h2 id="sqlite-default" tabindex="-1">SQLite (default) <a class="header-anchor" href="#sqlite-default" aria-label="Permalink to &quot;SQLite (default)&quot;">​</a></h2><p>Nothing to configure. The database file is created at <code>.data/piwi.db</code> on the first API call, inside the directory you mounted as <code>/app/.data</code> (container) or the working directory you ran from (<code>npx</code>).</p><p>Set <code>PIWI_DATABASE_PATH</code> to put it somewhere else:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-IKEQn" id="tab-6lJrwO3" checked><label data-title="Docker" for="tab-6lJrwO3">Docker</label><input type="radio" name="group-IKEQn" id="tab-dtmnf38"><label data-title=".env" for="tab-dtmnf38">.env</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.data:/app/.data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PIWI_DATABASE_PATH=/app/.data/custom.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenx/piwitests-server:latest</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_DATABASE_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/custom/path/database.db</span></span></code></pre></div></div></div><p>SQLite allows one writer at a time. That is ample for a team&#39;s test volume — a run submission is a short burst of writes — but if you run several dashboard replicas against one database, or see <code>database is locked</code> under load, move to PostgreSQL.</p><h2 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h2><p>Set <code>PIWI_DATABASE_URL</code> and Piwi uses PostgreSQL instead of SQLite, creating and migrating every table on startup. PostgreSQL <strong>14+</strong>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgresql://user:password@localhost:5432/piwi_dashboard</span></span></code></pre></div><p><code>PIWI_DATABASE_PATH</code> is ignored while <code>PIWI_DATABASE_URL</code> is set. A ready-to-run Compose stack with a <code>postgres:17-alpine</code> service is in the <a href="./deployment.html#docker-compose-with-postgresql">deployment guide</a>.</p><p>To try it locally against a throwaway server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5432:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_USER=postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_PASSWORD=postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_DB=piwi_dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres:17-alpine</span></span></code></pre></div><h2 id="switching-backends" tabindex="-1">Switching backends <a class="header-anchor" href="#switching-backends" aria-label="Permalink to &quot;Switching backends&quot;">​</a></h2><p>There is <strong>no migration path between SQLite and PostgreSQL</strong> — pointing an instance at a new backend gives you an empty dashboard, not a converted one. Switch before you accumulate history you care about, or accept starting fresh. Your file storage is unaffected either way.</p><h2 id="retention-and-backups" tabindex="-1">Retention and backups <a class="header-anchor" href="#retention-and-backups" aria-label="Permalink to &quot;Retention and backups&quot;">​</a></h2><ul><li><strong>Retention</strong> — the nightly sweep prunes runs older than <code>PIWI_RETENTION_DAYS</code>, off by default. See <a href="./storage.html#data-retention">Data retention</a>.</li><li><strong>Backups</strong> — SQLite has an online-consistent backup recipe, PostgreSQL uses <code>pg_dump</code>. Both, plus what to copy alongside the database, are in <a href="./deployment.html#backups">Backups</a>.</li><li><strong>Upgrades apply migrations automatically and they are forward-only.</strong> Read <a href="./upgrading.html">Upgrading</a> before bumping a version tag.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/reference/configuration.html#database">Configuration reference</a> — every <code>PIWI_DATABASE_*</code> and retention variable</li><li><a href="./storage.html">Storage configuration</a> — where reports, traces and attachments go</li><li><a href="./deployment.html">Deployment</a> — Compose, Kubernetes and one-click templates</li><li>Changing the schema is a contributor task, not an operator one: <a href="https://github.com/PiwiTests/platform/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a></li></ul>',20)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
